// Payload Normalizer & Deduplication Fingerprinting
const crypto = require('crypto');
const input = $json.body || $json;

let alerts = [];
if (input.alerts && Array.isArray(input.alerts)) {
  // Prometheus format
  alerts = input.alerts.map(a => ({
    source: 'prometheus',
    alert_name: a.labels?.alertname || a.annotations?.summary || 'Prometheus Alert',
    description: a.annotations?.description || a.annotations?.message || JSON.stringify(a),
    severity: a.labels?.severity || 'Medium',
    service: a.labels?.job || a.labels?.service || 'infrastructure',
    instance: a.labels?.instance || 'unknown',
    raw_payload: a
  }));
} else {
  // Custom / Grafana format
  alerts = [{
    source: input.source || 'custom',
    alert_name: input.alert_name || input.ruleName || input.title || 'IT Alert',
    description: input.description || input.message || JSON.stringify(input),
    severity: input.severity || 'Medium',
    service: input.service || 'service',
    instance: input.instance || 'host',
    raw_payload: input
  }];
}

return alerts.map(a => {
  const rawKey = `${a.source}::${a.alert_name}::${a.service}::${a.instance}`.toLowerCase();
  const fingerprint = crypto.createHash('sha256').update(rawKey).digest('hex');
  return { json: { ...a, fingerprint } };
});
